const communityDescriptions=['Las 74 personas siguen en el mundo. Tras recibir relevo dejan su tarea industrial y vuelven al barrio. Por la noche descansan dentro de las casas.','De 12:00 a 14:00 las personas paran para comer y desplazarse. En este escenario hay un único turno de trabajo humano de ocho horas.','Cada robot reserva dos horas de recarga y una de mantenimiento por día. Los horarios se escalonan para que otros robots puedan mantener la actividad.','Después de las pruebas, hasta el 70 % de los robots vuelve a la red si hace falta. Tardan dos horas simuladas en llegar a su destino. El resto sale hacia otros usos.','La red recibe electricidad e insumos especializados del exterior. Los paneles representan el suministro, no un cálculo de autosuficiencia energética.'];
function updateInspector(){const f=run.frames[index],i=selected;$('place-title').textContent=places[i].name;$('place-description').textContent=i<9?INDUSTRIES[i].description:communityDescriptions[i-9];$('industrial-detail').hidden=i>=9;
  if(i<9){updateProduction(i);const status=processStatus(f,nextFrame(),i);$('place-humans').textContent=f.humans[i];$('place-workers').textContent=f.robots[i];$('place-flow').textContent=f.flow[i]*(i===1?4:1);$('place-product').textContent=INDUSTRIES[i].product+' / última hora';$('place-status').textContent=status.label+(f.projects[i]?' · obra al '+Math.round(f.projects[i].progress/f.projects[i].required*100)+' %':'');$('place-status').dataset.state=status.code;$('place-shift').textContent=f.humansWorking[i]+' personas y '+f.active[i]+' robots disponibles ahora.';
    $('stock-list').replaceChildren(...INPUTS[i].map(k=>{const row=document.createElement('div');row.className='stock-row'+(f.inventory[k]===0?' empty':'');const name=document.createElement('span');name.textContent=RESOURCES[k];const count=document.createElement('strong');count.textContent=format(f.inventory[k]);row.append(name,count);return row;}));$('stock-title').textContent=i===0?'Extracción limitada por equipos':'Existencias que necesita';$('stock-footnote').textContent=i===0?'Los insumos especializados y la energía vienen del exterior.':'Lotes en la red · pilas del mapa orientativas';$('capacity-fill').style.width=Math.min(100,status.rate/f.hardware[i]*100)+'%';$('capacity-label').textContent=status.rate+' / '+f.hardware[i]+' lotes por hora';
  }else{$('place-status').dataset.state='';$('place-status').textContent=i===9?f.humansReplaced+' personas con su tarea industrial cubierta por robots.':i===10?f.period==='lunch'?'Es la hora de comer.':'El comedor espera la siguiente pausa.':i===11?totals(f.charging)+' recargando · '+totals(f.maintenance)+' en mantenimiento':i===12?format(f.exported)+' robots destinados a otros usos.':'Suministro externo supuesto.';}
}
function selectPlace(i,narrate=true){if(i<9)traceIndex=i;selected=i;$('inspector').hidden=false;zoomTarget=container.clientWidth<680?4:2.8;targetLook.set(places[i].x,0,places[i].z);updateUI();if(narrate)narrator.explain('district-'+i,i<9?'state-'+processStatus(run.frames[index],nextFrame(),i).code:null);}
function resetCamera(){selected=-1;$('inspector').hidden=true;zoomTarget=1;yawTarget=.58;targetLook.set(-1,0,3);updateUI();}
$('routes').addEventListener('click',()=>{showRoutes=!showRoutes;needsFrame=true;$('routes').setAttribute('aria-pressed',showRoutes);});
$('close-inspector').addEventListener('click',()=>{selected=-1;$('inspector').hidden=true;updateUI();});
function updateCamera(){yaw+=(yawTarget-yaw)*.12;zoom+=(zoomTarget-zoom)*.12;look.lerp(targetLook,.09);const aspect=container.clientWidth/container.clientHeight,size=Math.max(41,67/aspect);camera.left=-size*aspect/zoom;camera.right=size*aspect/zoom;const lift=container.clientWidth<680?size*(selected>=0?-.34:.14):0;camera.top=(size+lift)/zoom;camera.bottom=(-size+lift)/zoom;camera.position.set(look.x+Math.sin(yaw)*110,90,look.z+Math.cos(yaw)*110);camera.lookAt(look);camera.updateProjectionMatrix();camera.updateMatrixWorld();}
