$('zoom-in').addEventListener('click',()=>zoomTarget=Math.min(4,zoomTarget*1.25));$('zoom-out').addEventListener('click',()=>zoomTarget=Math.max(.75,zoomTarget/1.25));$('camera-reset').addEventListener('click',resetCamera);
$('fullscreen').addEventListener('click',async()=>{const panel=document.querySelector('.simulation-shell');try{if(document.fullscreenElement)await document.exitFullscreen();else await panel.requestFullscreen();}catch{panel.classList.toggle('expanded');}});
let pointer=null,pinchDistance=0,pinching=false;
const fingers=new Map(),raycaster=new THREE.Raycaster(),groundPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0),hit=new THREE.Vector3();
const fingerDistance=()=>{const [a,b]=[...fingers.values()];return a&&b?Math.hypot(a.x-b.x,a.y-b.y):0;};
renderer.domElement.addEventListener('pointerdown',e=>{fingers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(fingers.size===1){pinching=false;pointer={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY};}else{pinching=true;pinchDistance=fingerDistance();}renderer.domElement.setPointerCapture(e.pointerId);container.classList.add('dragging');});
renderer.domElement.addEventListener('pointermove',e=>{if(!fingers.has(e.pointerId))return;fingers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(fingers.size>=2){const distance=fingerDistance();if(pinchDistance>0)zoomTarget=THREE.MathUtils.clamp(zoomTarget*distance/pinchDistance,.75,4);pinchDistance=distance;return;}if(!pointer||pinching)return;const dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;if(e.shiftKey)yawTarget+=dx*.005;else{const units=(camera.top-camera.bottom)/container.clientHeight;targetLook.x-=dx*units*Math.cos(yaw)+dy*units*Math.sin(yaw)*1.55;targetLook.z+=dx*units*Math.sin(yaw)-dy*units*Math.cos(yaw)*1.55;targetLook.x=THREE.MathUtils.clamp(targetLook.x,-48,48);targetLook.z=THREE.MathUtils.clamp(targetLook.z,-40,47);}pointer.x=e.clientX;pointer.y=e.clientY;});
renderer.domElement.addEventListener('pointerup',e=>{if(!pinching&&pointer&&Math.hypot(e.clientX-pointer.startX,e.clientY-pointer.startY)<6){const r=container.getBoundingClientRect();raycaster.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);if(raycaster.ray.intersectPlane(groundPlane,hit)){const i=places.findIndex(p=>Math.abs(p.x-hit.x)<8&&Math.abs(p.z-hit.z)<7);if(i>=0)selectPlace(i);}}fingers.delete(e.pointerId);pointer=null;if(!fingers.size){pinching=false;container.classList.remove('dragging');}});
renderer.domElement.addEventListener('pointercancel',e=>{fingers.delete(e.pointerId);pointer=null;if(!fingers.size){pinching=false;container.classList.remove('dragging');}});
renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();zoomTarget=THREE.MathUtils.clamp(zoomTarget*Math.exp(-e.deltaY*.001),.75,4);},{passive:false});
const mini=$('minimap'),ctx=mini.getContext('2d');function mapPoint(x,z){return {x:(x+50)/100*mini.width,y:(z+43)/92*mini.height};}
function drawMiniMap(){const f=run.frames[index],w=mini.width,h=mini.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#132635';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#34505e';ctx.lineWidth=2;[-14,8,31,44].forEach(z=>{const p=mapPoint(0,z);ctx.beginPath();ctx.moveTo(0,p.y);ctx.lineTo(w,p.y);ctx.stroke();});[-43,-23,0,24,45].forEach(x=>{const p=mapPoint(x,0);ctx.beginPath();ctx.moveTo(p.x,0);ctx.lineTo(p.x,h);ctx.stroke();});places.forEach((p,i)=>{const a=mapPoint(p.x,p.z);ctx.fillStyle=i===selected?'#ff9c62':i<9&&f.robots[i]?'#acdacc':i<9?'#87a4ba':'#cfb98c';ctx.fillRect(a.x-8,a.y-6,16,12);});const p=mapPoint(look.x,look.z);ctx.strokeStyle='#ffb581';ctx.lineWidth=1.4;const d=31/zoom;ctx.strokeRect(p.x-d,p.y-d*.75,d*2,d*1.5);ctx.fillStyle='#ffb581';ctx.beginPath();ctx.arc(p.x,p.y,2,0,Math.PI*2);ctx.fill();}
mini.addEventListener('click',e=>{const r=mini.getBoundingClientRect();targetLook.set((e.clientX-r.left)/r.width*100-50,0,(e.clientY-r.top)/r.height*92-43);zoomTarget=Math.max(zoomTarget,1.8);});
mini.addEventListener('keydown',e=>{const d={ArrowLeft:[-6,0],ArrowRight:[6,0],ArrowUp:[0,-6],ArrowDown:[0,6]}[e.key];if(d){e.preventDefault();targetLook.x=THREE.MathUtils.clamp(targetLook.x+d[0],-48,48);targetLook.z=THREE.MathUtils.clamp(targetLook.z+d[1],-40,47);}if(e.key==='Enter')resetCamera();});
function drawGrowth(){$('growth-current').textContent=format(run.frames[index].total);$('growth-reference').textContent=format(baseline.frames[index].total);const canvas=$('growth-chart'),c=canvas.getContext('2d'),w=canvas.width,h=canvas.height;c.clearRect(0,0,w,h);const peak=Math.max(1,run.frames[index].total,baseline.frames[index].total),left=8,right=w-8,top=10,bottom=h-15;
  c.strokeStyle='#405369';c.lineWidth=1;for(let j=0;j<3;j++){const y=top+(bottom-top)*j/2;c.beginPath();c.moveTo(left,y);c.lineTo(right,y);c.stroke();}
  [baseline.frames,run.frames].forEach((frames,k)=>{c.strokeStyle=k?'#ffac75':'#8297b2';c.lineWidth=k?2.5:1.5;c.setLineDash(k?[]:[4,4]);c.beginPath();for(let j=0;j<=index;j++){const x=left+(right-left)*j/Math.max(24,index),y=bottom-frames[j].total/peak*(bottom-top);if(j===0)c.moveTo(x,y);else c.lineTo(x,y);}c.stroke();c.setLineDash([]);});
  c.font='11px system-ui';c.fillStyle='#8da4bc';c.fillText('Inicio',left,h-1);c.textAlign='right';c.fillText('Día '+run.frames[index].day,right,h-1);c.textAlign='left';canvas.setAttribute('aria-label','Robots acumulados hasta el día '+run.frames[index].day+': '+run.frames[index].total+' en esta estrategia y '+baseline.frames[index].total+' reforzando solo montaje.');
}
const milestoneDefinitions=[{id:'beginning',label:'Inicio',find:f=>f.step===0,site:7},{id:'handover',label:'Relevos',find:f=>f.humansReplaced>=1,site:null},{id:'construction',label:'Ampliaciones',find:f=>f.started.length>0,site:null},{id:'networked',label:'Red robotizada',find:f=>f.humansReplaced===74,site:null}];
function updateMilestones(){milestoneDefinitions.forEach(m=>{const f=run.frames.find(m.find),b=$(m.id);b.disabled=!f;b.title=f?'Día '+f.day+' · '+String(f.hour).padStart(2,'0')+':00':'Este escenario no alcanza este momento';b.setAttribute('aria-pressed',Boolean(f&&index===f.step));});}
milestoneDefinitions.forEach(m=>$(m.id).addEventListener('click',()=>{const f=run.frames.find(m.find);if(!f)return;playing=false;phase=0;setHour(f.step);if(m.site!==null)selectPlace(m.site);else if(m.id==='handover')selectPlace(f.arrivals.indexOf(Math.max(...f.arrivals)));else if(m.id==='construction')selectPlace(f.started[0]);else resetCamera();container.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}));
function resize(){updateProduction();if(selected>=0&&selected<9)updateProduction(selected);needsFrame=true;renderer.setSize(container.clientWidth,container.clientHeight,false);updateCamera();}new ResizeObserver(resize).observe(container);
function setHour(next){index=THREE.MathUtils.clamp(next,0,run.frames.length-1);updateUI();}
let clock=performance.now(),motionClock=performance.now();const hourSeconds=1.55;
function stepClock(){const now=performance.now(),dt=Math.min((now-clock)/1000,.4);clock=now;if(!playing)return;phase+=dt*speed/hourSeconds;while(phase>=1&&playing){phase--;if(index>=run.frames.length-1){playing=false;phase=0;updateUI();}else setHour(index+1);}updateClock();}
setInterval(stepClock,50);
$('play').addEventListener('click',()=>{if(playing){stepClock();playing=false;}else{if(index===run.frames.length-1){phase=0;setHour(0);}playing=true;clock=performance.now();}updateUI();});
$('time').addEventListener('input',e=>{playing=false;phase=0;setHour(Number(e.target.value));});$('speed').addEventListener('change',e=>{stepClock();speed=Number(e.target.value);});
document.querySelectorAll('[data-hour]').forEach(b=>b.addEventListener('click',()=>{playing=false;phase=0;setHour((run.frames[index].day-1)*24+Number(b.dataset.hour)-run.startHour);}));$('next-day').addEventListener('click',()=>{playing=false;phase=0;setHour(index+24);});
function changeScenario(next=policy){playing=false;phase=0;policy=next;run=simulateIndustry(policy,$('expand').checked);baseline=simulateIndustry('assembly',$('expand').checked);planProduction=INDUSTRIES.map((_,i)=>productionSeries(run.frames,i));liveRows=districtRows(run.frames,humanReference.frames);characters.rebuild(run);setHour(index);['network','assembly','none'].forEach(id=>$(id).setAttribute('aria-pressed',id===policy));}
['network','assembly','none'].forEach(id=>$(id).addEventListener('click',()=>changeScenario(id)));$('expand').addEventListener('change',()=>changeScenario());
$('about-button').addEventListener('click',()=>$('about').showModal());$('close-about').addEventListener('click',()=>$('about').close());$('about').addEventListener('click',e=>{if(e.target===$('about'))$('about').close();});
